import {openWorkbook,cellAt,fromCol,toCol,findCellCandidates} from './workbook-parser.js';
import {sampleModel,compileModel,simulate,impactOf,metricRows,validateBindings} from './dependency-engine.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>typeof n==='number'?new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n):String(n??'—');
const short=n=>{if(typeof n!=='number'||!Number.isFinite(n))return'—';return Math.abs(n)>=1e8?fmt(n/1e8)+'亿':Math.abs(n)>=1e4?fmt(n/1e4)+'万':fmt(n);};
let state={projects:[],current:null,book:null,loaded:new Map(),result:null,token:0};
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function openDb(){return new Promise((yes,no)=>{const r=indexedDB.open('game-balance-lab-workbooks-v1',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('projects'))r.result.createObjectStore('projects',{keyPath:'id'});};r.onsuccess=()=>yes(r.result);r.onerror=()=>no(r.error);});}
async function storeOp(type,action){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('projects',type),req=action(tx.objectStore('projects'));let result;req.onsuccess=()=>result=req.result;req.onerror=()=>reject(req.error);tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(tx.error);};});}
const all=()=>storeOp('readonly',s=>s.getAll()),save=r=>storeOp('readwrite',s=>s.put(r)),deleteProject=id=>storeOp('readwrite',s=>s.delete(id));
function renderProjects(){$('projectCount').textContent=state.projects.length;$('projectList').innerHTML=state.projects.map(r=>`<button class="project-item ${state.current?.id===r.id?'active':''}" data-project="${esc(r.id)}"><strong>◈ ${esc(r.title)}</strong><small>${r.file?esc(r.filename):'虚构示例，无 Excel'} · ${new Date(r.created).toLocaleDateString('zh-CN')}</small></button>`).join('')||'<p class="small-help">还没有项目。可导入 Excel 或体验示例。</p>';}
function showEmpty(flag){$('empty').hidden=!flag;$('workspace').hidden=flag;$('exportJson').disabled=flag;$('exportCsv').disabled=flag;$('topProject').textContent=flag?'未选择项目':state.current?.title||'项目';}
function initProject(title,file=null){const depModel=sampleModel();depModel.name=title;return{id:`dep-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,title,filename:file?.name||'',created:Date.now(),file:file?new Blob([file]):null,depModel,depOutput:'power',depImpact:'baseattack',depLevels:30};}
async function createDemo(){const r=initProject('RPG 属性与经济 · 虚构示例');await save(r);state.projects=await all();await chooseProject(r.id);toast('已创建虚构示例：可以修改攻击并观察战力、金币和成本变化。');}
async function upload(file){if(!file)return;try{toast('正在读取 Excel 结构，文件较大时会稍慢…');const wb=await openWorkbook(file);const rec=initProject(file.name.replace(/\.xlsx$|\.xlsm$/i,''),file);await save(rec);state.projects=await all();await chooseProject(rec.id);toast(`导入成功：${wb.sheets.length} 张 Sheet。请绑定你的输入单元格/列，并设置真实公式。`);}catch(e){toast('导入失败：'+e.message);}}
async function chooseProject(id){const rec=state.projects.find(r=>r.id===id);if(!rec)return;const token=++state.token;state.current=rec;state.book=null;state.loaded.clear();state.result=null;
 if(!rec.depModel){rec.depModel=sampleModel();rec.depLevels=30;rec.depOutput='power';rec.depImpact='baseattack';await save(rec);}
 if(rec.file){try{state.book=await openWorkbook(new File([rec.file],rec.filename));}catch(e){toast('读取工作簿失败：'+e.message);}}if(token!==state.token)return;
 showEmpty(false);$('projectName').textContent=rec.title;$('projectSubtitle').textContent=(rec.filename?`${rec.filename} · ${state.book?.sheets.length||0} 张 Sheet`:'虚构示例数值')+' · 显式公式依赖计算';$('levels').value=rec.depLevels||30;
 renderProjects();renderEditor();await recalc();}
function inputNodes(){return state.current?.depModel.nodes.filter(n=>n.kind==='input')||[];}
function formulaNodes(){return state.current?.depModel.nodes.filter(n=>n.kind==='formula')||[];}
function sourceName(n){if(!n.source)return '示例/手动';return`${n.source.sheet}!${n.source.mode==='cell'?n.source.address:(n.source.column+':'+n.source.startRow)}`;}
function renderEditor(){const rec=state.current;if(!rec)return;
 $('inputsBody').innerHTML=inputNodes().map(n=>`<tr data-id="${esc(n.id)}"><td><strong>${esc(n.label||n.id)}</strong><span class="param-id">${esc(n.id)} ${esc(n.unit||'')}</span></td><td><input data-k="value" type="number" step="any" value="${Number(n.value)}" ${n.id==='level'?'disabled':''}></td><td><input data-k="factor" type="number" step="0.05" value="${Number(n.factor??1)}" ${n.id==='level'?'disabled':''}></td><td><input data-k="offset" type="number" step="any" value="${Number(n.offset??0)}" ${n.id==='level'?'disabled':''}></td><td><button class="source-chip" data-bind="${esc(n.id)}" title="点击设置 Excel 来源">${esc(sourceName(n))}</button></td></tr>`).join('');
 $('formulaList').innerHTML=formulaNodes().map(n=>`<div class="formula-row" data-id="${esc(n.id)}"><div class="formula-line"><div><strong>${esc(n.label||n.id)}</strong><code>${esc(n.id)}</code></div><button title="删除该节点" class="remove-node" data-remove="${esc(n.id)}">删除</button></div><input aria-label="${esc(n.label)} 的计算公式" data-formula="${esc(n.id)}" spellcheck="false" value="${esc(n.formula)}"></div>`).join('');
 const candidates=formulaNodes();$('outputSelect').innerHTML=candidates.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('');$('outputSelect').value=candidates.some(n=>n.id===rec.depOutput)?rec.depOutput:candidates[0]?.id||'';rec.depOutput=$('outputSelect').value;
 $('impactSelect').innerHTML=inputNodes().filter(n=>n.id!=='level').map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('');$('impactSelect').value=inputNodes().some(n=>n.id===rec.depImpact)?rec.depImpact:inputNodes().find(n=>n.id!=='level')?.id||'';rec.depImpact=$('impactSelect').value;
 $('bindingEmpty').hidden=!!state.book;$('bindingFields').hidden=!state.book;
 if(state.book){const previous=$('bindNode').value;$('bindNode').innerHTML=inputNodes().filter(n=>n.id!=='level').map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('');$('bindNode').value=inputNodes().some(n=>n.id===previous)?previous:(rec.depImpact||'baseattack');$('bindSheet').innerHTML=state.book.sheets.map(s=>`<option value="${esc(s.name)}">${esc(s.name)}</option>`).join('');setBindingForm();}}
function setBindingForm(){const n=inputNodes().find(n=>n.id===$('bindNode').value);if(!n||!state.book)return;const s=n.source||{mode:'cell',sheet:state.book.sheets[0]?.name,address:'B2',column:'B',startRow:2};$('bindSheet').value=state.book.sheets.some(x=>x.name===s.sheet)?s.sheet:state.book.sheets[0].name;$('bindMode').value=s.mode;$('bindRef').value=s.mode==='column'?s.column:s.address;$('bindStart').value=s.startRow||2;previewBinding();}
async function previewBinding(){if(!state.book)return;const sheet=$('bindSheet').value;if(!sheet)return;try{const data=await state.book.load(sheet);const mode=$('bindMode').value,ref=$('bindRef').value.trim().toUpperCase();let preview;if(mode==='cell'){const c=cellAt(data,ref);preview=`${sheet}!${ref}：${fmt(c?.v??'空白')}${c?.f?' · 原格含公式，读取的是上次保存的缓存值':''}`;}else{let nums=[];for(let i=0;i<5;i++)nums.push(fmt(cellAt(data,ref+(Number($('bindStart').value)+i))?.v??'空白'));preview=`${sheet}!${ref}${$('bindStart').value} 起，前 5 级：${nums.join(' / ')}`;}$('bindPreview').textContent=preview;}catch(e){$('bindPreview').textContent='预览失败：'+e.message;}}
async function loadMapped(){const loaded=new Map();if(!state.book)return loaded;const workbook=state.book;const names=[...new Set(inputNodes().map(n=>n.source?.sheet).filter(Boolean))];if(names.length>12)throw Error('一次推演最多绑定 12 个不同工作表');for(const name of names)loaded.set(name,await workbook.load(name));return loaded;}
function source(n,level,loaded){if(!n.source)return undefined;const s=n.source,d=loaded.get(s.sheet);if(!d)throw Error(`${n.label} 绑定的 Sheet 不可用`);const addr=s.mode==='cell'?s.address:s.column+(Number(s.startRow)+level-1);const c=cellAt(d,addr),v=c?.v;if(typeof v!=='number'||!Number.isFinite(v))throw Error(`${n.label}：${s.sheet}!${addr} 缺少有效数字（原 Excel 公式需先保存缓存值）`);return v;}
async function recalc(){const r=state.current;if(!r)return;const token=++state.token;try{const warnings=validateBindings(r.depModel,state.book);if(warnings.length)throw Error(warnings.join('；'));const loaded=await loadMapped();if(token!==state.token)return;const result=simulate(r.depModel,{levels:Number(r.depLevels),source:(n,l)=>source(n,l,loaded)});state.result=result;$('errorBar').hidden=true;renderResults();}catch(e){if(token!==state.token)return;state.result=null;$('errorBar').hidden=false;$('errorBar').textContent='无法计算：'+e.message;$('metrics').innerHTML='';$('depChart').innerHTML='<div class="chart-empty">请检查公式和 Excel 映射</div>';$('detailTable').textContent='暂无计算结果';$('impactNodes').textContent='修正错误后显示影响链';}}
function saveLater(){clearTimeout(saveLater.timeout);saveLater.timeout=setTimeout(async()=>{if(!state.current)return;try{await save(state.current);}catch(e){toast('项目保存失败：'+e.message);}},450);}
function schedule(){clearTimeout(schedule.timeout);schedule.timeout=setTimeout(()=>recalc(),140);saveLater();}
function renderResults(){const r=state.result;if(!r)return;const id=$('outputSelect').value,models=state.current.depModel.nodes,outputs=state.current.depModel.outputs||[],fav=[id,...outputs.filter(v=>v!==id)].slice(0,4);const last=r.baseline.length-1;
 $('metrics').innerHTML=fav.map(id=>{const n=models.find(v=>v.id===id);if(!n)return'';const a=r.baseline[last][id],b=r.scenario[last][id],d=b-a;return`<div class="metric"><span>${esc(n.label)}</span><strong>${short(b)}</strong><small>${esc(n.unit||'')} · 基准 ${short(a)}</small><div class="delta-mini ${d<0?'down':''}">${d>0?'+':''}${short(d)}（${a===0?'基准为0':(d/a*100).toFixed(1)+'%'}）</div></div>`;}).join('');
 renderChart(id);renderImpact();renderTable();const stat=r.stats;$('calcStats').textContent=`实际重算 ${stat.scenarioOps} 次 / 复用 ${stat.reused} 次`;
}
function renderChart(id){const r=state.result;if(!r)return;const points=metricRows(r,id);const w=820,h=310,l=67,rr=22,t=20,b=46;const all=points.flatMap(p=>[p.base,p.projected]);let lo=Math.min(...all),hi=Math.max(...all);if(hi===lo){lo-=1;hi+=1;}const margin=(hi-lo)*.06;lo-=margin;hi+=margin;const xx=i=>l+(i/(Math.max(1,points.length-1)))*(w-l-rr),yy=v=>h-b-(v-lo)/(hi-lo)*(h-b-t);const path=key=>points.map((p,i)=>`${i===0?'M':'L'}${xx(i).toFixed(2)},${yy(p[key]).toFixed(2)}`).join(' ');let grid='';for(let i=0;i<=4;i++){const y=t+(h-b-t)*i/4;grid+=`<line x1="${l}" y1="${y}" x2="${w-rr}" y2="${y}" stroke="#eceef5"/><text x="${l-10}" y="${y+4}" text-anchor="end" font-size="10" fill="#9aa6b9">${esc(short(hi-(hi-lo)*i/4))}</text>`;}
 $('depChart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="基准方案和依赖重算方案曲线">${grid}<path d="${path('base')}" stroke="#a5aec5" stroke-width="3" fill="none"/><path d="${path('projected')}" stroke="#675ce5" stroke-width="3.5" fill="none"/><text x="${l}" y="${h-12}" fill="#9ca6b6" font-size="11">Lv.1</text><text x="${w-rr}" y="${h-12}" text-anchor="end" fill="#9ca6b6" font-size="11">Lv.${points.length}</text><line x1="-10" x2="-10" y1="${t}" y2="${h-b}" id="hoverGuide" stroke="#b8b3e6" stroke-dasharray="5 5"/><rect x="${l}" y="${t}" width="${w-l-rr}" height="${h-t-b}" fill="transparent" id="depOverlay"/></svg>`;
 const overlay=$('depOverlay');overlay.addEventListener('pointermove',e=>{const svg=overlay.ownerSVGElement,m=svg.getScreenCTM();if(!m)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const pt=p.matrixTransform(m.inverse());const i=Math.max(0,Math.min(points.length-1,Math.round((pt.x-l)/(w-l-rr)*Math.max(1,points.length-1))));const row=points[i];$('hoverGuide').setAttribute('x1',xx(i));$('hoverGuide').setAttribute('x2',xx(i));$('hoverLineText').textContent=`Lv.${row.level} · A ${fmt(row.base)} → B ${fmt(row.projected)} · 差异 ${row.delta>=0?'+':''}${fmt(row.delta)}`;});}
function renderImpact(){const result=state.result;if(!result)return;const graph=result.graph,id=$('impactSelect').value;if(!graph.nodes.has(id))return;const affected=impactOf(graph,id);const order=result.order.filter(n=>affected.has(n));$('impactSummary').textContent=`关联 ${Math.max(0,order.length-1)} 个节点 · 以下为真实引用关系`;
 const edges=[];for(const to of order){for(const from of graph.deps.get(to)||[])if(affected.has(from))edges.push({from,to,when:'本级'});for(const from of graph.temporal.get(to)||[])if(affected.has(from))edges.push({from,to,when:'跨级'});}
 const name=key=>esc(graph.nodes.get(key)?.label||key);const last=result.baseline.length-1;
 $('impactNodes').innerHTML=`<div class="impact-edges">${edges.map(({from,to,when})=>`<div class="impact-edge"><span>${name(from)}</span><b>→</b><span>${name(to)}</span><small>${when}</small></div>`).join('')||'<p class="small-help">当前输入参数尚未被其他公式引用。</p>'}</div><div class="impact-totals">${order.map(key=>{const change=result.scenario[last][key]-result.baseline[last][key];return`<div class="impact-node ${key===id?'origin':''}">${name(key)}<small>末级变化 ${change>0?'+':''}${fmt(change)}</small></div>`;}).join('')}</div>`;}
function renderTable(){const r=state.result;if(!r)return;const wanted=[...new Set([$('outputSelect').value,'attack','power','upgradecost','goldincome','goldbalance'].filter(id=>r.graph.nodes.has(id)))].slice(0,6),rows=r.baseline.length;const step=rows>120?Math.ceil(rows/120):1;
 $('rowsTag').textContent=`${rows} 级 · ${wanted.length} 个指标`;$('detailTable').innerHTML=`<table><thead><tr><th>等级</th>${wanted.map(id=>`<th colspan="2">${esc(r.graph.nodes.get(id).label)}</th>`).join('')}</tr><tr><th>Lv.</th>${wanted.map(()=>'<th>A 基准</th><th>B 调整后</th>').join('')}</tr></thead><tbody>${r.baseline.map((b,i)=>{if(i%step&&i!==rows-1)return'';const x=r.scenario[i];return`<tr><td>${i+1}</td>${wanted.map(id=>`<td>${fmt(b[id])}</td><td class="${x[id]>b[id]?'value-up':x[id]<b[id]?'value-down':''}">${fmt(x[id])}</td>`).join('')}</tr>`;}).join('')}</tbody></table>`;}
function csvExport(){const r=state.result;if(!r)return toast('先运行一轮计算');const cols=state.current.depModel.nodes.map(n=>n.id),data=[['等级',...cols.flatMap(id=>[id+'_A',id+'_B',id+'_delta'])]];r.baseline.forEach((b,i)=>data.push([i+1,...cols.flatMap(id=>[b[id],r.scenario[i][id],r.scenario[i][id]-b[id]])]));const csv='\ufeff'+data.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('Game_Balance_Lab_依赖推演.csv',new Blob([csv],{type:'text/csv;charset=utf-8'}));}
function download(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function addNode(kind){const id=prompt(kind==='input'?'新输入参数 ID（英文字母、数字、下划线）':'新公式节点 ID（英文字母、数字、下划线）');if(!id)return;const label=prompt('节点中文名称',id)||id;const model=state.current.depModel;model.nodes.push(kind==='input'?{id:id.toLowerCase(),label,kind,value:1,unit:'',factor:1,offset:0}:{id:id.toLowerCase(),label,kind,formula:'level*2',unit:''});try{compileModel(model);}catch(e){model.nodes.pop();return toast(e.message);}renderEditor();schedule();}
function wire(){for(const id of ['uploadSide','uploadTop','uploadEmpty'])$(id).onclick=()=>{$('fileInput').value='';$('fileInput').click();};$('fileInput').onchange=e=>upload(e.target.files?.[0]);for(const id of ['createDemo','demoEmpty'])$(id).onclick=createDemo;
 $('projectList').onclick=e=>{const b=e.target.closest('[data-project]');if(b)chooseProject(b.dataset.project);};$('levels').onchange=e=>{const value=Number(e.target.value);if(!Number.isInteger(value)||value<1||value>500)return toast('请输入 1–500 级');state.current.depLevels=value;schedule();};
 $('inputsBody').addEventListener('change',e=>{const el=e.target;if(el.tagName!=='INPUT')return;const tr=el.closest('[data-id]'),n=inputNodes().find(n=>n.id===tr?.dataset.id);if(!n)return;const v=Number(el.value);if(!Number.isFinite(v))return toast('请输入有效数字');n[el.dataset.k]=v;schedule();});
 $('inputsBody').onclick=e=>{const b=e.target.closest('[data-bind]');if(!b)return;$('bindNode').value=b.dataset.bind;setBindingForm();document.querySelector('#bindingFields').scrollIntoView({behavior:'smooth',block:'nearest'});};
 $('formulaList').addEventListener('change',e=>{const el=e.target.closest('[data-formula]');if(!el)return;const n=formulaNodes().find(n=>n.id===el.dataset.formula);if(n){n.formula=el.value.trim();schedule();}});
 $('formulaList').onclick=e=>{const b=e.target.closest('[data-remove]');if(!b)return;const id=b.dataset.remove;if(!confirm(`删除节点 ${id}？若其他公式引用它，需要先修改那些公式。`))return;state.current.depModel.nodes=state.current.depModel.nodes.filter(n=>n.id!==id);renderEditor();schedule();};
 $('addInput').onclick=()=>addNode('input');$('addFormula').onclick=()=>addNode('formula');$('impactSelect').onchange=e=>{state.current.depImpact=e.target.value;renderImpact();saveLater();};$('outputSelect').onchange=e=>{state.current.depOutput=e.target.value;renderResults();saveLater();};
 $('bindNode').onchange=setBindingForm;$('bindMode').onchange=e=>{$('bindRef').value=e.target.value==='cell'?'B2':'B';previewBinding();};for(const id of ['bindSheet','bindRef','bindStart'])$(id).addEventListener('change',previewBinding);
 $('saveBinding').onclick=async()=>{const n=inputNodes().find(n=>n.id===$('bindNode').value);if(!n)return;const mode=$('bindMode').value,ref=$('bindRef').value.trim().toUpperCase();const item={mode,sheet:$('bindSheet').value,...(mode==='cell'?{address:ref}:{column:ref,startRow:Number($('bindStart').value)})};n.source=item;renderEditor();schedule();toast(`已绑定 ${n.label} → ${item.sheet}!${ref}`);};
 $('clearBinding').onclick=()=>{const n=inputNodes().find(n=>n.id===$('bindNode').value);if(n){delete n.source;renderEditor();schedule();toast('已取消 Excel 绑定');}};
 $('scanSheet').onclick=async()=>{const sheet=$('bindSheet').value;try{const data=await state.book.load(sheet);const list=findCellCandidates(data,200).slice(0,30);$('candidateList').innerHTML='<div class="candidates">'+list.map(v=>`<button data-pick="${esc(v.cell)}" title="${esc(v.label)}">${esc(v.label)} · ${esc(v.cell)}=${fmt(v.value)}</button>`).join('')+'</div>';if(!list.length)toast('没有发现邻近标签的纯数字单元格，可手动指定单元格或列');}catch(e){toast(e.message);}};
 $('candidateList').onclick=e=>{const b=e.target.closest('[data-pick]');if(!b)return;$('bindMode').value='cell';$('bindRef').value=b.dataset.pick;previewBinding();};
 $('exportCsv').onclick=csvExport;$('exportJson').onclick=()=>{if(!state.current)return;const r=state.current;const obj={app:'Game Balance Lab',version:'1.6',project:r.title,sourceFilename:r.filename||null,model:r.depModel,levels:r.depLevels,selectedOutput:r.depOutput,notice:'此文件只包含显式依赖模型定义/映射，不包含 Excel 原始工作簿。'};download('Game_Balance_Lab_模型配置.json',new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));};
 $('rename').onclick=async()=>{if(!state.current)return;const newName=prompt('项目名称',state.current.title)?.trim();if(!newName)return;state.current.title=newName.slice(0,100);await save(state.current);$('projectName').textContent=state.current.title;$('topProject').textContent=state.current.title;renderProjects();};
 $('remove').onclick=async()=>{if(!state.current)return;if(!confirm('从当前浏览器删除项目与缓存的原始 Excel？（不会删除你电脑上的文件）'))return;await deleteProject(state.current.id);state.projects=await all();state.current=null;state.book=null;state.result=null;renderProjects();showEmpty(true);if(state.projects.length)await chooseProject(state.projects[0].id);};}
async function boot(){wire();try{state.projects=await all();renderProjects();if(state.projects.length)await chooseProject(state.projects[0].id);else showEmpty(true);}catch(e){showEmpty(true);toast('浏览器 IndexedDB 不可用：'+e.message);}}boot();
